1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>資本支出 IRR 效益追蹤</title>
7	<style>
8	:root{
9	  color-scheme:light;
10	  --bg:#EDEFEC;--panel:#FFFFFF;--ink:#1D2733;--muted:#5F6B76;--line:#D5D9D4;--soft:#F5F6F4;
11	  --plan:#8C97A3;--act:#0E6B65;--act-soft:#E2F0EE;--neg:#B23A2E;--neg-soft:#F8E7E4;
12	  --pos:#2B7A4B;--pos-soft:#E5F2EA;--warn:#9A6514;--warn-soft:#FBF0DC;
13	  --font:"Noto Sans TC","Microsoft JhengHei UI","Microsoft JhengHei","PingFang TC",system-ui,sans-serif;
14	  --frozen-w:220px;
15	}
16	*{box-sizing:border-box}
17	html,body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.6 var(--font)}
18	.num{font-variant-numeric:tabular-nums;text-align:right;white-space:nowrap}
19	a{color:var(--act)}
20	button,input,select,textarea{font:inherit;color:inherit}
21	:focus-visible{outline:2px solid var(--act);outline-offset:2px}
22	header.top{background:var(--ink);color:#fff;display:flex;align-items:center;gap:20px;padding:0 24px;min-height:56px;flex-wrap:wrap}
23	header.top h1{font-size:16px;font-weight:600;margin:0;letter-spacing:.02em}
24	header.top nav{display:flex;gap:2px;flex:1;flex-wrap:wrap}
25	header.top nav a{color:#C8D0D8;text-decoration:none;padding:16px 12px;border-bottom:3px solid transparent}
26	header.top nav a.on{color:#fff;border-bottom-color:#5FC4B8}
27	header.top nav a .badge{background:#5FC4B8;color:var(--ink);border-radius:9px;padding:0 6px;font-size:12px;margin-left:4px;font-weight:600}
28	.clock{display:flex;align-items:center;gap:6px;font-size:13px;color:#C8D0D8}
29	.clock input{background:#2C3846;border:1px solid #46525F;color:#fff;border-radius:4px;padding:2px 6px;width:140px}
30	.clock input::-webkit-calendar-picker-indicator{filter:invert(1);opacity:.85;cursor:pointer}
31	main{max-width:1300px;margin:0 auto;padding:28px 24px 80px}
32	h2{font-size:22px;font-weight:600;margin:0 0 4px}
33	h3{font-size:16px;font-weight:600;margin:0 0 12px}
34	.lead{color:var(--muted);margin:0 0 24px}
35	.panel{background:var(--panel);border:1px solid var(--line);border-radius:6px;padding:20px 22px;margin-bottom:20px}
36	.muted{color:var(--muted)}
37	.small{font-size:12.5px}
38	.btn{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--act);background:var(--act);color:#fff;padding:7px 16px;border-radius:4px;cursor:pointer;text-decoration:none;font-weight:500;white-space:nowrap}
39	.btn:hover{background:#0A5550}
40	.btn.ghost{background:#fff;color:var(--act)}
41	.btn.ghost:hover{background:var(--act-soft)}
42	.btn.danger{background:#fff;color:var(--neg);border-color:#D9A39C}
43	.btn.danger:hover{background:var(--neg-soft)}
44	.btn:disabled{opacity:.45;cursor:not-allowed}
45	.btn.sm{padding:3px 10px;font-size:13px}
46	table{border-collapse:collapse;width:100%}
47	th,td{padding:7px 10px;border-bottom:1px solid var(--line);vertical-align:middle}
48	th{font-weight:600;text-align:left;color:var(--muted);font-size:12.5px;background:var(--soft)}
49	tr.clickable{cursor:pointer}
50	tr.clickable:hover td{background:#F4F8F7}
51	.tag{display:inline-block;border-radius:3px;padding:0 7px;font-size:12px;line-height:20px;white-space:nowrap}
52	.tag.ok{background:var(--pos-soft);color:var(--pos)}
53	.tag.due{background:var(--warn-soft);color:var(--warn)}
54	.tag.late{background:var(--neg-soft);color:var(--neg)}
55	.tag.idle{background:var(--soft);color:var(--muted);border:1px solid var(--line)}
56	.tag.auto{background:var(--soft);color:var(--muted)}
57	.d-neg{color:var(--neg)}
58	.d-pos{color:var(--pos)}
59	.irr-hero{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:8px 28px;padding:24px 28px}
60	.irr-hero .fig .lab{color:var(--muted);font-size:13px}
61	.irr-hero .fig .val{font-size:44px;font-weight:300;line-height:1.1;font-variant-numeric:tabular-nums;letter-spacing:-.01em}
62	.irr-hero .fig.plan .val{color:var(--plan)}
63	.irr-hero .fig.act .val{color:var(--act);font-weight:500}
64	.irr-hero .slope{height:70px}
65	.irr-hero .delta{grid-column:1/-1;display:flex;gap:28px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:12px;margin-top:6px;align-items:center}
66	.tracker-wrap{position:relative;overflow:hidden;border-radius:0 0 6px 6px}
67	.tracker-scroll{overflow-x:auto;margin-left:var(--frozen-w)}
68	.tracker-frozen{position:absolute;left:0;top:0;width:var(--frozen-w);z-index:10;background:var(--panel)}
69	.tracker-frozen table{width:var(--frozen-w);table-layout:fixed;border-collapse:collapse}
70	.tracker-frozen table td,.tracker-frozen table th{border-bottom:1px solid var(--line);border-right:2px solid var(--line);padding:0 10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:var(--panel);vertical-align:middle}
71	.tracker-scroll table{border-collapse:collapse;white-space:nowrap}
72	.tracker-scroll table th,.tracker-scroll table td{border-bottom:1px solid var(--line);border-left:1px solid var(--line);padding:0;vertical-align:middle}
73	.yr-head-wrap{display:flex;flex-direction:column;text-align:center}
74	.yr-name{font-weight:600;font-size:12.5px;padding:5px 8px 2px;display:flex;align-items:center;justify-content:center;gap:6px}
75	.yr-period{font-size:11px;color:var(--muted);padding:0 8px 3px}
76	.yr-status{font-size:11px;padding:2px 6px 4px;min-height:18px}
77	.yr-sub{display:flex;border-top:1px solid var(--line)}
78	.yr-sub-cell{flex:1;text-align:center;padding:3px 6px;font-size:11px;color:var(--muted)}
79	.yr-sub-cell.act-label{color:var(--act)}
80	.yr-sub-cell+.yr-sub-cell{border-left:1px solid var(--line)}
81	.col-plan{width:90px;min-width:90px;text-align:right;font-size:13px;padding:5px 8px;font-variant-numeric:tabular-nums}
82	.col-act{width:106px;min-width:106px;text-align:right;font-size:13px;padding:3px 5px;font-variant-numeric:tabular-nums}
83	.t-inp{border:1.5px solid #3F7FBF;border-radius:3px;padding:3px 6px;width:94px;text-align:right;background:#fff;font-size:13px;font-variant-numeric:tabular-nums;display:block}
84	.t-inp.filled{border-color:var(--act);background:#EDF7F5}
85	.t-inp:invalid{border-color:var(--neg);background:var(--neg-soft)}
86	.irr-bar{position:sticky;bottom:0;background:var(--ink);color:#fff;display:flex;align-items:stretch;border-top:2px solid var(--act);z-index:30;box-shadow:0 -4px 16px rgba(0,0,0,.18)}
87	.irr-bar-inner{display:flex;align-items:center;gap:20px;padding:10px 20px;flex:1;flex-wrap:wrap}
88	.irr-fig{display:flex;flex-direction:column;line-height:1.2;min-width:100px}
89	.irr-fig .l{font-size:11px;color:#8C97A3}
90	.irr-fig .v{font-size:22px;font-weight:600;font-variant-numeric:tabular-nums}
91	.irr-fig.plan .v{color:var(--plan)}
92	.irr-fig.act .v{color:#5FC4B8}
93	.irr-arrow{font-size:18px;color:#46525F}
94	.irr-diff{font-size:14px;font-weight:600}
95	.irr-diff.pos{color:#5FC4B8}
96	.irr-diff.neg{color:#EF8C84}
97	.irr-save{padding:10px 20px;border-left:1px solid #2C3846;display:flex;flex-direction:column;justify-content:center;gap:5px;min-width:200px}
98	.save-btn{background:var(--act);color:#fff;border:none;border-radius:4px;padding:8px 20px;cursor:pointer;font-weight:600;font-size:14px;white-space:nowrap}
99	.save-btn:disabled{opacity:.4;cursor:not-allowed}
100	.save-btn:hover:not(:disabled){background:#0A5550}
101	.yr-menu-wrap{position:relative;display:inline-block}
102	.yr-menu-btn{background:none;border:1px solid #46525F;color:#C8D0D8;border-radius:3px;padding:1px 6px;cursor:pointer;font-size:11px;line-height:1.6}
103	.yr-menu-btn:hover{background:#2C3846}
104	.yr-menu{display:none;position:absolute;top:100%;right:0;background:var(--panel);border:1px solid var(--line);border-radius:4px;box-shadow:0 4px 16px rgba(0,0,0,.12);z-index:50;min-width:140px}
105	.yr-menu.open{display:block}
106	.yr-menu button{display:block;width:100%;text-align:left;padding:7px 14px;border:0;background:none;cursor:pointer;font-size:13px;color:var(--ink)}
107	.yr-menu button:hover{background:var(--soft)}
108	.yr-menu button.danger{color:var(--neg)}
109	.drop{border:2px dashed #AEB7B2;border-radius:6px;background:#F7F8F6;padding:44px 20px;text-align:center;cursor:pointer}
110	.drop.over{border-color:var(--act);background:var(--act-soft)}
111	.drop strong{display:block;font-size:16px;margin-bottom:4px}
112	.err{background:var(--neg-soft);color:var(--neg);border-radius:4px;padding:10px 14px;margin:12px 0}
113	.note{background:var(--warn-soft);color:#6B4A10;border-radius:4px;padding:10px 14px;margin:12px 0}
114	.okbox{background:var(--pos-soft);color:#1F5C38;border-radius:4px;padding:10px 14px;margin:12px 0}
115	label.f{display:block;margin-bottom:12px}
116	label.f span{display:block;font-size:12.5px;color:var(--muted);margin-bottom:3px}
117	input[type=text],input[type=email],input[type=date],input[type=number],select,textarea{border:1px solid #C3C9C4;border-radius:4px;padding:6px 9px;background:#fff;width:100%}
118	.grid2{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:0 20px}
119	.seg{display:inline-flex;border:1px solid #C3C9C4;border-radius:4px;overflow:hidden}
120	.seg button{border:0;background:#fff;padding:3px 10px;font-size:12.5px;cursor:pointer}
121	.seg button.on{background:var(--act);color:#fff}
122	.empty{padding:36px 10px;text-align:center;color:var(--muted)}
123	.toast{position:fixed;left:50%;bottom:72px;transform:translateX(-50%);background:var(--ink);color:#fff;padding:10px 18px;border-radius:4px;box-shadow:0 4px 18px rgba(20,30,40,.25);z-index:999;pointer-events:none}
124	.notice{border:1px solid var(--line);border-radius:6px;background:#fff;margin-bottom:10px}
125	.notice summary{display:flex;gap:10px;align-items:center;padding:10px 14px;cursor:pointer;list-style:none;flex-wrap:wrap}
126	.notice summary::-webkit-details-marker{display:none}
127	.notice .ch{font-size:11.5px;border:1px solid var(--line);border-radius:3px;padding:0 6px;color:var(--muted)}
128	.notice pre{margin:0;padding:12px 14px;border-top:1px solid var(--line);background:var(--soft);white-space:pre-wrap;font:13px/1.7 var(--font)}
129	.modal-overlay{display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.4);z-index:200;align-items:center;justify-content:center}
130	.modal-overlay.show{display:flex}
131	.modal{background:var(--panel);border-radius:6px;padding:24px;max-width:520px;width:90%;box-shadow:0 10px 40px rgba(0,0,0,.2)}
132	.modal h3{margin-top:0}
133	.modal-buttons{display:flex;gap:8px;justify-content:flex-end;margin-top:20px}
134	.storage-bar{height:4px;background:var(--line);border-radius:2px;margin-top:8px;overflow:hidden}
135	.storage-bar-fill{height:100%;border-radius:2px;transition:width .3s}
136	@media(max-width:760px){
137	  .irr-hero{grid-template-columns:1fr}
138	  .irr-hero .slope{display:none}
139	  main{padding:20px 14px 80px}
140	  :root{--frozen-w:160px}
141	}
142	</style>
143	</head>
144	<body>
145	<header class="top">
146	  <h1>資本支出 IRR 效益追蹤</h1>
147	  <nav id="nav"></nav>
148	  <label class="clock" title="調整系統日期以模擬年度回報提醒">系統日期 <input type="date" id="today"></label>
149	</header>
150	<main id="app"></main>
151	<div id="modal" class="modal-overlay" role="dialog" aria-modal="true">
152	  <div class="modal">
153	    <h3 id="modal-title"></h3>
154	    <div id="modal-body"></div>
155	    <div class="modal-buttons">
156	      <button class="btn ghost" id="modal-cancel">取消</button>
157	      <button class="btn" id="modal-ok">確定</button>
158	    </div>
159	  </div>
160	</div>
161	<script>
162	(function(root){'use strict';
163	function unesc(s){return s.replace(/&(lt|gt|amp|quot|apos|#x[0-9a-fA-F]+|#\d+);/g,function(m,e){if(e==='lt')return'<';if(e==='gt')return'>';if(e==='amp')return'&';if(e==='quot')return'"';if(e==='apos')return"'";if(e[1]==='x')return String.fromCodePoint(parseInt(e.slice(2),16));return String.fromCodePoint(parseInt(e.slice(1),10));});}
164	function attr(s,name){var m=new RegExp('(?:^|\\s)'+name+'="([^"]*)"').exec(s);return m?unesc(m[1]):null;}
165	function colToNum(c){var n=0;for(var i=0;i<c.length;i++)n=n*26+(c.charCodeAt(i)-64);return n;}
166	function numToCol(n){var s='';while(n>0){var m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=(n-m-1)/26;}return s;}
167	function splitAddr(a){var m=/^\$?([A-Z]{1,3})\$?(\d+)$/.exec(a);return m?{c:colToNum(m[1]),r:+m[2]}:null;}
168	function addr(r,c){return numToCol(c)+r;}
169	async function readZip(u8,inflateRaw,wanted){var dv=new DataView(u8.buffer,u8.byteOffset,u8.byteLength);var eocd=-1;for(var i=u8.length-22;i>=Math.max(0,u8.length-70000);i--){if(dv.getUint32(i,true)===0x06054b50){eocd=i;break;}}if(eocd<0)throw new Error('檔案不是有效的 .xlsx');var n=dv.getUint16(eocd+10,true);var p=dv.getUint32(eocd+16,true);var out={};var dec=new TextDecoder('utf-8');for(var k=0;k<n;k++){if(dv.getUint32(p,true)!==0x02014b50)break;var method=dv.getUint16(p+10,true);var csize=dv.getUint32(p+20,true);var nlen=dv.getUint16(p+28,true),xlen=dv.getUint16(p+30,true),clen=dv.getUint16(p+32,true);var lho=dv.getUint32(p+42,true);var name=dec.decode(u8.subarray(p+46,p+46+nlen));p+=46+nlen+xlen+clen;if(wanted&&!wanted(name))continue;var lnl=dv.getUint16(lho+26,true),lxl=dv.getUint16(lho+28,true);var start=lho+30+lnl+lxl;var data=u8.subarray(start,start+csize);var raw;if(method===0)raw=data;else if(method===8)raw=await inflateRaw(data);else continue;out[name]=dec.decode(raw);}return out;}
170	async function parseWorkbook(u8,inflateRaw){var files=await readZip(u8,inflateRaw,function(n){return/^xl\/(workbook\.xml|_rels\/workbook\.xml\.rels|sharedStrings\.xml|worksheets\/sheet\d+\.xml)$/.test(n);});var wbx=files['xl/workbook.xml'];if(!wbx)throw new Error('找不到 workbook.xml');var rels={};(files['xl/_rels/workbook.xml.rels']||'').replace(/<Relationship\b([^>]*)\/?>/g,function(m,a){rels[attr(a,'Id')]=attr(a,'Target');});var ss=[];var sst=files['xl/sharedStrings.xml']||'';sst.replace(/<si>([\s\S]*?)<\/si>/g,function(m,inner){inner=inner.replace(/<rPh\b[\s\S]*?<\/rPh>/g,'');var t='';inner.replace(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g,function(m2,x){t+=unesc(x);});ss.push(t);});var sheets={},order=[];var sheetRe=/<sheet\b([^>]*)\/>/g;var m;while((m=sheetRe.exec(wbx))){var sname=attr(m[1],'name');var rid=attr(m[1],'r:id');var target=rels[rid]||'';target=target.replace(/^\/?xl\//,'').replace(/^\//,'');var xml=files['xl/'+target];order.push(sname);sheets[sname]=xml?parseSheet(xml,ss):{cells:{}};}return{sheets:sheets,order:order};}
171	function parseSheet(xml,ss){var cells={};var masters={};var re=/<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g;var m;var pend=[];while((m=re.exec(xml))){var a=m[1],inner=m[2]||'';var r=attr(a,'r');var t=attr(a,'t');var v=null,f=null;var vm=/<v>([\s\S]*?)<\/v>/.exec(inner);if(vm){var raw=unesc(vm[1]);if(t==='s')v=ss[+raw];else if(t==='str')v=raw;else if(t==='b')v=raw==='1';else if(t==='e')v={err:raw};else v=+raw;}else if(t==='inlineStr'){var sv='';inner.replace(/<t(?:\s[^>]*)?>([\s\S]*?)<\/t>/g,function(q,x){sv+=unesc(x);});v=sv;}var fm=/<f\b([^>]*?)(?:\/>|>([\s\S]*?)<\/f>)/.exec(inner);if(fm){var fa=fm[1];var ftxt=fm[2]!=null?unesc(fm[2]):'';if(attr(fa,'t')==='shared'){var si=attr(fa,'si');if(ftxt){masters[si]={r:r,f:ftxt};f=ftxt;}else pend.push({r:r,si:si});}else if(ftxt)f=ftxt;}if(v===null&&f===null)continue;cells[r]={v:v,f:f};}for(var pi=0;pi<pend.length;pi++){var pd=pend[pi];var ms=masters[pd.si];if(!ms)continue;var pa=splitAddr(ms.r),pb=splitAddr(pd.r);var pf=shiftFormula(ms.f,pb.r-pa.r,pb.c-pa.c);if(!cells[pd.r])cells[pd.r]={v:null,f:pf};else cells[pd.r].f=pf;}return{cells:cells};}
172	var REF_RE=/^(\$?)([A-Z]{1,3})(\$?)(\d+)(?::(\$?)([A-Z]{1,3})(\$?)(\d+))?/;
173	function tokenize(src){var toks=[];var i=0;while(i<src.length){var ch=src[i];if(ch===' '||ch==='\n'||ch==='\r'||ch==='\t'){i++;continue;}if(ch==='"'){var j=i+1,str='';while(j<src.length){if(src[j]==='"'){if(src[j+1]==='"'){str+='"';j+=2;continue;}break;}str+=src[j++];}toks.push({t:'str',v:str,raw:src.slice(i,j+1)});i=j+1;continue;}if(ch==='#'){var em=/^#(NULL!|DIV\/0!|VALUE!|REF!|NAME\?|NUM!|N\/A)/.exec(src.slice(i));if(em){toks.push({t:'err',v:em[0],raw:em[0]});i+=em[0].length;continue;}}var sheet=null,ext=false,ji=i;if(ch==="'"){var k=i+1,nm='';while(k<src.length){if(src[k]==="'"){if(src[k+1]==="'"){nm+="'";k+=2;continue;}break;}nm+=src[k++];}if(src[k+1]==='!'){sheet=nm;ji=k+2;}}else{var sm=/^(\[\d+\])?([^\s!'"(),+\-*\/^&=<>:;{}%]+)!/.exec(src.slice(i));if(sm){sheet=sm[2];ext=!!sm[1];ji=i+sm[0].length;}}if(sheet!==null){if(/^\[\d+\]/.test(sheet)){ext=true;sheet=sheet.replace(/^\[\d+\]/,'');}var rm=REF_RE.exec(src.slice(ji));if(rm){toks.push(mkRef(rm,sheet,ext,src.slice(i,ji+rm[0].length),src.slice(i,ji)));i=ji+rm[0].length;continue;}var er=/^#REF!/.exec(src.slice(ji));if(er){toks.push({t:'err',v:'#REF!',raw:src.slice(i,ji+5)});i=ji+5;continue;}throw new Error('無法解析的參照：'+src.slice(i,i+30));}var num=/^(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?/.exec(src.slice(i));if(num&&!/^[A-Z]/.test(src.slice(i))){toks.push({t:'num',v:parseFloat(num[0]),raw:num[0]});i+=num[0].length;continue;}var fn=/^([A-Za-z_][A-Za-z0-9_.]*)\(/.exec(src.slice(i));if(fn){toks.push({t:'fn',v:fn[1].toUpperCase().replace(/^_XLFN\./,''),raw:fn[0]});i+=fn[0].length;continue;}var rref=REF_RE.exec(src.slice(i));if(rref&&!/^[A-Za-z0-9_]/.test(src.slice(i+rref[0].length))){toks.push(mkRef(rref,null,false,rref[0],''));i+=rref[0].length;continue;}var bool=/^(TRUE|FALSE)(?![A-Za-z0-9_])/i.exec(src.slice(i));if(bool){toks.push({t:'bool',v:bool[1].toUpperCase()==='TRUE',raw:bool[0]});i+=bool[0].length;continue;}var op=/^(<>|<=|>=|[-+*\/^&=<>%(),:;{}])/.exec(src.slice(i));if(op){toks.push({t:'op',v:op[0],raw:op[0]});i+=op[0].length;continue;}var nmx=/^[A-Za-z_\\][A-Za-z0-9_.\\]*/.exec(src.slice(i));if(nmx){toks.push({t:'name',v:nmx[0],raw:nmx[0]});i+=nmx[0].length;continue;}throw new Error('無法解析的字元：'+src.slice(i,i+10));}return toks;}
