file.content:
.save-btn:hover:not(:disabled){background:#0A5550}
.yr-menu-wrap{position:relative;display:inline-block}
.yr-menu-btn{background:none;border:1px solid #46525F;color:#C8D0D8;border-radius:3px;padding:1px 6px;cursor:pointer;font-size:11px;line-height:1.6}
.yr-menu-btn:hover{background:#2C3846}
.yr-menu{display:none;position:absolute;top:100%;right:0;background:var(--panel);border:1px solid var(--line);border-radius:4px;box-shadow:0 4px 16px rgba(0,0,0,.12);z-index:50;min-width:140px}
.yr-menu.open{display:block}
.yr-menu button{display:block;width:100%;text-align:left;padding:7px 14px;border:0;background:none;cursor:pointer;font-size:13px;color:var(--ink)}
.yr-menu button:hover{background:var(--soft)}
.yr-menu button.danger{color:var(--neg)}
.drop{border:2px dashed #AEB7B2;border-radius:6px;background:#F7F8F6;padding:44px 20px;text-align:center;cursor:pointer}
.drop.over{border-color:var(--act);background:var(--act-soft)}
.drop strong{display:block;font-size:16px;margin-bottom:4px}
.err{background:var(--neg-soft);color:var(--neg);border-radius:4px;padding:10px 14px;margin:12px 0}
.note{background:var(--warn-soft);color:#6B4A10;border-radius:4px;padding:10px 14px;margin:12px 0}
.okbox{background:var(--pos-soft);color:#1F5C38;border-radius:4px;padding:10px 14px;margin:12px 0}
label.f{display:block;margin-bottom:12px}
label.f span{display:block;font-size:12.5px;color:var(--muted);margin-bottom:3px}
input[type=text],input[type=email],input[type=date],input[type=number],select,textarea{border:1px solid #C3C9C4;border-radius:4px;padding:6px 9px;background:#fff;width:100%}
.grid2{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:0 20px}
.seg{display:inline-flex;border:1px solid #C3C9C4;border-radius:4px;overflow:hidden}
.seg button{border:0;background:#fff;padding:3px 10px;font-size:12.5px;cursor:pointer}
.seg button.on{background:var(--act);color:#fff}
.empty{padding:36px 10px;text-align:center;color:var(--muted)}
.toast{position:fixed;left:50%;bottom:72px;transform:translateX(-50%);background:var(--ink);color:#fff;padding:10px 18px;border-radius:4px;box-shadow:0 4px 18px rgba(20,30,40,.25);z-index:999;pointer-events:none}
.notice{border:1px solid var(--line);border-radius:6px;background:#fff;margin-bottom:10px}
.notice summary{display:flex;gap:10px;align-items:center;padding:10px 14px;cursor:pointer;list-style:none;flex-wrap:wrap}
.notice summary::-webkit-details-marker{display:none}
.notice .ch{font-size:11.5px;border:1px solid var(--line);border-radius:3px;padding:0 6px;color:var(--muted)}
.notice pre{margin:0;padding:12px 14px;border-top:1px solid var(--line);background:var(--soft);white-space:pre-wrap;font:13px/1.7 var(--font)}
.modal-overlay{display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.4);z-index:200;align-items:center;justify-content:center}
.modal-overlay.show{display:flex}
.modal{background:var(--panel);border-radius:6px;padding:24px;max-width:520px;width:90%;box-shadow:0 10px 40px rgba(0,0,0,.2)}
.modal h3{margin-top:0}
.modal-buttons{display:flex;gap:8px;justify-content:flex-end;margin-top:20px}
.storage-bar{height:4px;background:var(--line);border-radius:2px;margin-top:8px;overflow:hidden}
.storage-bar-fill{height:100%;border-radius:2px;transition:width .3s}
@media(max-width:760px){
  .irr-hero{grid-template-columns:1fr}
  .irr-hero .slope{display:none}
  main{padding:20px 14px 80px}
  :root{--frozen-w:160px}
}
