function parse(src){var toks=tokenize(src);var i=0;function next(){return toks[i++];}function isOp(v){return toks[i]&&toks[i].t==='op'&&toks[i].v===v;}function expr(){return cmp();}function cmp(){var l=cat();while(toks[i]&&toks[i].t==='op'&&['=','<>','<','>','<=','>='].indexOf(toks[i].v)>=0){var o=next().v;l={k:'bin',o:o,l:l,r:cat()};}return l;}function cat(){var l=add();while(isOp('&')){next();l={k:'bin',o:'&',l:l,r:add()};}return l;}function add(){var l=mul();while(isOp('+')||isOp('-')){var o=next().v;l={k:'bin',o:o,l:l,r:mul()};}return l;}function mul(){var l=pow();while(isOp('*')||isOp('/')){var o=next().v;l={k:'bin',o:o,l:l,r:pow()};}return l;}function pow(){var l=una();while(isOp('^')){next();l={k:'bin',o:'^',l:l,r:una()};}return l;}function una(){if(isOp('-')){next();return{k:'neg',e:una()};}if(isOp('+')){next();return una();}return pct();}function pct(){var e=prim();while(isOp('%')){next();e={k:'pct',e:e};}return e;}function prim(){var t=next();if(!t)throw new Error('公式不完整');if(t.t==='num')return{k:'lit',v:t.v};if(t.t==='str')return{k:'lit',v:t.v};if(t.t==='bool')return{k:'lit',v:t.v};if(t.t==='err')return{k:'lit',v:{err:t.v}};if(t.t==='ref')return{k:'ref',sheet:t.sheet,ext:t.ext,a:t.a,b:t.b};if(t.t==='name')return{k:'name',v:t.v};if(t.t==='fn'){var args=[];if(isOp(')')){next();return{k:'fn',n:t.v,args:args};}while(true){if(isOp(',')){args.push({k:'lit',v:null});next();continue;}args.push(expr());if(isOp(',')){next();if(isOp(')'))args.push({k:'lit',v:null});continue;}if(isOp(')')){next();break;}throw new Error('函數參數格式錯誤');}return{k:'fn',n:t.v,args:args};}if(t.t==='op'&&t.v==='('){var e=expr();if(!isOp(')'))throw new Error('括號不成對');next();return e;}throw new Error('無法解析：'+t.raw);}var e=expr();if(i<toks.length)throw new Error('公式有多餘內容：'+toks[i].raw);return e;}
function XErr(e){this.err=e;}
