      if (!p.reports) p.reports = {};
      if (!p.mode) p.mode = 'formula';
      if (!p.reportRows) p.reportRows = [];
    }
  }
  return raw;
}

function loadDb() {
  try { var s = localStorage.getItem(KEY); if (s) return migrateDb(JSON.parse(s)); } catch(e) {}
