(function(root) {
  'use strict';

  function unesc(s) {
    return s.replace(/&(lt|gt|amp|quot|apos|#x[0-9a-fA-F]+|#\d+);/g, function(m, e) {
      if (e === 'lt') return '<';
      if (e === 'gt') return '>';
